source('research/mercado-laboral-dominicano/postgresql-recovery/expansion/common.R')
con<-connect_pg(readonly=TRUE);central<-connect_pg('censos_linea_tiempo',readonly=TRUE)
macro<-dbGetQuery(con,'SELECT count(ipc) AS ipc,count(inflacion_interanual) AS inflacion,count(imae_interanual) AS imae,count(tpm_porcentaje) AS tpm,count(remesas_usd) AS remesas,count(canasta_nacional_dop) AS canasta FROM analitica.macro_mensual')
stopifnot(all(as.numeric(macro[1,])>0))
wdi<-dbGetQuery(con,'SELECT count(*) AS lotes,sum(filas_con_datos) AS observaciones FROM meta.wdi_cargas')
stopifnot(wdi$lotes==150,as.numeric(wdi$observaciones)==dbGetQuery(con,'SELECT count(*) AS n FROM banco_mundial.observaciones')$n)
dgcp<-dbGetQuery(con,'SELECT count(*) AS cargas,sum(filas) AS filas FROM meta.dgcp_cargas');stopifnot(dgcp$cargas==156)
local_views<-dbGetQuery(con,"SELECT table_name FROM information_schema.views WHERE table_schema='analitica' ORDER BY 1")$table_name
central_views<-dbGetQuery(central,"SELECT foreign_table_name FROM information_schema.foreign_tables WHERE foreign_table_schema='fdw_economia' ORDER BY 1")$foreign_table_name
stopifnot(identical(local_views,central_views),length(local_views)==35L)
sources<-dbGetQuery(central,"SELECT count(*) AS n FROM catalogo.fuentes WHERE base_datos='economia_rd'")$n;stopifnot(sources==13)
quality<-dbGetQuery(central,"SELECT count(*) AS controles,count(*) FILTER(WHERE estado='error') AS errores FROM fdw_economia.calidad_datos")
stopifnot(quality$controles==24,quality$errores==0)
dates<-dbGetQuery(con,"SELECT 'compras_fecha_version' AS concepto,min(fecha_version) AS desde,max(fecha_version) AS hasta FROM analitica.compras_procesos UNION ALL SELECT 'presupuesto_vista',min(periodo),max(periodo) FROM analitica.presupuesto_mensual")
write_json(list(status='ok',checked_at=format(Sys.time(),'%Y-%m-%dT%H:%M:%S%z'),macro_observaciones=macro,wdi=wdi,dgcp=dgcp,views=length(local_views),central_catalog_entries=as.integer(sources),quality=quality,dates=dates),file.path(base,'qa/final-smoke.json'),pretty=TRUE,auto_unbox=TRUE)
cat('Final checks: macro values present; WDI/DGCP batches reconcile; all 35 views and 13 sources available centrally.\n')
dbDisconnect(con);dbDisconnect(central)
